sub=activeSub();st.submission=sub?.id||'';rt=sub?readiness(sub.id):null;
if(st.editor?.error)st.showExtra=true;
const mobileNav={desk:'Desk',tracker:'Tracker',plan:'Content plan',documents:'Documents',questions:'Questions',readiness:'Readiness'};
const nav=templateLayoutSchema.screens.filter(x=>tabs.includes(x.id)).sort((a,b)=>tabs.indexOf(a.id)-tabs.indexOf(b.id)).map(x=>'<button type="button" class="rg-nav-btn '+(st.screen===x.id?'active':'')+'" data-action="nav:'+x.id+'">'+icon(x.id,18)+'<span class="rg-desktop-label">'+h(x.label)+'</span><span class="rg-mobile-label">'+h(mobileNav[x.id])+'</span></button>').join('');
